<?php $title='Verify ID'; require __DIR__.'/../includes/header.php'; $token=basename($_SERVER['REQUEST_URI']); $stmt=db()->prepare('SELECT m.*,d.name department FROM members m LEFT JOIN departments d ON d.id=m.department_id WHERE m.verify_token=? AND m.status="active" LIMIT 1'); $stmt->execute([$token]); $m=$stmt->fetch(); ?>
<main class="auth-page"><section class="glass-card auth-card text-center"><?php if($m): ?><span class="badge-verified">Online Verification Badge</span><img class="rounded-circle my-4" width="132" height="132" style="object-fit:cover" src="/<?= e($m['photo'] ?: 'assets/images/avatar.svg') ?>"><h1 class="h3"><?= e($m['full_name']) ?></h1><p class="text-muted"><?= e($m['member_uid']) ?> • <?= e($m['department']) ?></p><div class="list-group text-start"><div class="list-group-item">Status: <?= e($m['status']) ?></div><div class="list-group-item">Joining Date: <?= e($m['joining_date']) ?></div><div class="list-group-item">Verification: QR token matched securely</div></div><?php else: ?><h1 class="h4 text-danger">ID Not Verified</h1><p>The scanned card is invalid, expired or disabled.</p><?php endif; ?></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
